import { requireOptionalNativeModule } from 'expo';
import type { AudioPlayer } from 'expo-audio';
import { Platform } from 'react-native';

/**
 * The hold-to-arm ramp's sounds (`useRampedHold`): one click per countdown beat, then the arm.
 * Generated by `scripts/gen-hold-sounds.mjs`.
 *
 * expo-audio is required LAZILY, behind a probe for its native module, because its entry point
 * calls `requireNativeModule` at import: on a dev client built before it was added, a static import
 * would throw on launch, and these clicks are not worth a crash. Without the module the ramp is
 * simply silent.
 */
const SOURCES = [
  require('../../assets/sounds/hold-1.wav'),
  require('../../assets/sounds/hold-2.wav'),
  require('../../assets/sounds/hold-3.wav'),
  require('../../assets/sounds/hold-arm.wav'),
] as const;

let players: AudioPlayer[] | null | undefined;

function load(): AudioPlayer[] | null {
  if (players !== undefined) return players;
  if (Platform.OS !== 'web' && !requireOptionalNativeModule('ExpoAudio')) return (players = null);
  // eslint-disable-next-line @typescript-eslint/no-require-imports -- must not load before the probe above
  const audio: typeof import('expo-audio') = require('expo-audio');
  // `ambient` on iOS: the mute switch silences it and it mixes under whatever is already playing.
  // Both are off by default (playsInSilentMode defaults to TRUE), which for UI clicks is wrong.
  void audio.setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(() => {});
  // Kept active so iOS doesn't deactivate the session after every click — that's a round-trip
  // through the audio daemon between beats, and it also notifies other apps each time.
  return (players = SOURCES.map((source) => audio.createAudioPlayer(source, { keepAudioSessionActive: true })));
}

/** Creates the players and rewinds them, so a beat is a bare `play()` with nothing ahead of it —
 *  a seek is async, and one per beat would push the click behind the haptic it belongs to. Call
 *  on press-in: the first beat is 200ms away. */
export function primeHoldSounds() {
  for (const player of load() ?? []) void player.seekTo(0).catch(() => {});
}

/** `beat` 0–2 are the countdown ticks, 3 is the arm. */
export function playHoldSound(beat: number) {
  load()?.[beat]?.play();
}
